<?php
 namespace QQWorld\Framework\Filter; class Truncate implements \Zend_Filter_Interface { protected $length; protected $etc; protected $remainder; protected $breakWords; protected $string; public function __construct( \QQWorld\Framework\Stdlib\StringUtils $string, $length = 80, $etc = '...', &$remainder = '', $breakWords = true ) { $this->string = $string; $this->length = $length; $this->etc = $etc; $this->remainder = & $remainder; $this->breakWords = $breakWords; } public function filter($string) { $length = $this->length; $this->remainder = ''; if (0 == $length) { return ''; } $originalLength = $this->string->strlen($string); if ($originalLength > $length) { $length -= $this->string->strlen($this->etc); if ($length <= 0) { return ''; } $preparedString = $string; $preparedLength = $length; if (!$this->breakWords) { $preparedString = preg_replace('/\s+?(\S+)?$/u', '', $this->string->substr($string, 0, $length + 1)); $preparedLength = $this->string->strlen($preparedString); } $this->remainder = $this->string->substr($string, $preparedLength, $originalLength); return $this->string->substr($preparedString, 0, $length) . $this->etc; } return $string; } } 